loadNavbar
-------------------------------------------

* Type: `Boolean|String`
* Default: `false`

Loads navbar from the Markdown file `_navbar.md` if **true**, else loads it from the path specified.

```
window.$docsify = {
  // load from _navbar.md
  loadNavbar: true,

  // load from nav.md
  loadNavbar: 'nav.md',
};
```

loadSidebar
---------------------------------------------

* Type: `Boolean|String`
* Default: `false`

Loads sidebar from the Markdown file `_sidebar.md` if **true**, else loads it from the path specified.

```
window.$docsify = {
  // load from _sidebar.md
  loadSidebar: true,

  // load from summary.md
  loadSidebar: 'summary.md',
};
```

logo
-------------------------------

* Type: `String`

Website logo as it appears in the sidebar. You can resize it using CSS.

Logo will only be visible if `name` prop is also set. See [name](#/configuration?id=name) configuration.

```
window.$docsify = {
  logo: '/_media/icon.svg',
};
```

markdown
---------------------------------------

* Type: `Function`

See [Markdown configuration](#/markdown).

```
window.$docsify = {
  // object
  markdown: {
    smartypants: true,
    renderer: {
      link() {
        // ...
      },
    },
